def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    rich_pressure = 0.0
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) > budget:
                    rich_pressure = max(rich_pressure, float(bid))

    slots = supply / WATER_REQ
    tight = slots < 1.5
    medium_tight = slots < 2.0

    if not alive_opps:
        return float(min(budget, 20.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    danger = 0
    if hp <= 3:
        danger += 2
    elif hp <= 5:
        danger += 1
    if no_water_days >= 2:
        danger += 2
    elif no_water_days >= 1:
        danger += 1
    if tight:
        danger += 1

    if danger >= 4:
        bid = max(0.95 * DAILY_SALARY, highest_prev + 3.0)
    elif danger >= 2:
        bid = max(0.78 * DAILY_SALARY, highest_prev + 1.5)
    else:
        if tight:
            bid = max(0.62 * DAILY_SALARY, avg_prev * 0.9)
        elif medium_tight:
            bid = max(0.48 * DAILY_SALARY, avg_prev * 0.72)
        else:
            bid = 0.38 * DAILY_SALARY

    if highest_prev >= 170:
        if hp > 5 and no_water_days == 0:
            bid = min(bid, 30.0)
        else:
            bid = max(bid, 66.0)
    elif highest_prev >= 120:
        bid = max(bid, min(highest_prev + 2.0, 0.92 * DAILY_SALARY))

    if rich_pressure >= 120 and hp > 5 and no_water_days == 0 and tight:
        bid = min(bid, 32.0)

    if day >= 8:
        bid += 4.0
    if hp <= 2:
        bid = max(bid, 68.0)

    reserve = 0.0
    if hp > 5 and no_water_days == 0:
        reserve = 20.0
    elif hp > 3:
        reserve = 10.0

    cap = max(0.0, budget - reserve)
    if cap <= 0:
        cap = budget

    bid = min(bid, cap)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
